        "id": "sec-phys-1-6",
        "title": "Formation and Repair of Tissue",
        "content": [
          "Tissue repair is the replacement of wornout, damaged, or dead cells. New cells originate by cell division from the stroma, the supporting connective tissue, or from the parenchyma, cells that constitute the functioning part of the tissue or organ.In adults, each of the four basic tissue types;epithelial, connective, muscular and nervoushas a different capacity for replenishing parenchymalcells lost by damage, disease or other processes.",
          "Epithelial tissues (cells), which endure considerable wear and tear (and even injury) in some locations, have a continuous capacity for renewal. In some cases, immature, undifferentiated cells called \u2018stem cells\u2019divide to replace lost or damaged cells,e.g., stem cells reside in protected locations in the epithelia of the skin and gastrointestinal tract to replenish cells sloughed fromthe apical layer, and stem cells in red bone marrow continually provide new red blood cells, white blood cells and platelets. In other cases, mature, differentiated cells can undergo cell division; e.g. hepatocytes (liver cells) and endothelial cells in blood vessels.",
          "Some connective tissues also have a continuous capacity for renewal. One example is bone, which has an ample blood supply.",
          "Connective tissues such as cartilage can replenish cells much less readily, in part because of a smaller blood supply.",
          "Muscular tissue has a relatively poor capacity for renewal of lost cells. Even though skeletal muscle tissue contains stem cells called \u2018satellite cells\u2019; they do not divide rapidly enough to replace extensively damaged muscle fibers. Cardiac muscle tissue lacks satellite cells, and existing cardiac muscle fibers do not undergo mitosis to form new cells. Recent evidence suggests that stem cells do migrate into the heart from the blood.",
          "There, they can differentiate and replace a limited number of cardiac muscle fibers and endothelial cells in heart blood vessels. Smooth muscle fibers can proliferate to some extent, butthey do so much more slowly than the cells of epithelial or connective tissues.",
          "Nervous tissue has the poorest capacity for renewal. Although experiments have revealed the presence of some stem cells in the brain, they normally do not undergo mitosis to replace damaged neurons.",
          "The restoration of an injured tissue or organ to normal structure and function depends entirely on whether parenchymal cells are active in the repair process. If parenchymal cells accomplish the repair, tissue regenerationis possible, and a near perfect reconstruction of the injured tissue may occur.However, if fibroblasts of the stroma are active in the repair, the replacement tissue will be a new connective tissue. The fibroblasts synthesize collagen and other matrix materials thataggregate to form scar tissue, a process known as \u2018fibrosis\u2019. Because scar tissue is not specialized to perform the functions of the parenchymal tissue, the original function of the tissue or organ is impaired."
        ],
