        "title": "Functions",
        "content": [
          "Serous layers separated by a thin layer of serous fluid which is secreted by both membranes. Serous fluid allows organs to slide easily without friction (heart, stomach, etc.).",
          "Serosa lining abdominal cavity is peritoneum. In the thorax, serous membranes isolate lungs and heart from each other.",
          "Around the lungs is the pleura; the heart, pericardium.",
          "Cutaneous membrane: The cutaneous membrane or skin covers the entire surface of the body and consists of a superficial portion called the \u2018epidermis\u2019 and a deeper portion called the\u2018dermis\u2019."
        ],
        "points": [
          "Cutaneous membrane: The cutaneous membrane or skin covers the entire surface of the body and consists of a superficial portion called the \u2018epidermis\u2019 and a deeper portion called the\u2018dermis\u2019."
        ],
        "clinicalPearl": "**Clinical Pearl:** A benign tumor: is a neoplasm that does not metastasize.",
