        "title": "Functions of nose and nasal cavity",
        "content": [
          "Respiratory function: Warming, moistening, and filtering incoming air. Warming is due to immense vascularity of the mucosa. Filtering and cleaning of air occurs as hairs at the anterior nares trap large particles. Smaller particles such as dust and microbes settle and adhere to the mucus. Cilia of mucous membrane drift the mucus towards the throat where it is swallowed or expectorated.",
          "Detecting olfactory stimuli: There are nerve endings and fibers that detect smell, located in the roof of the nose in the area of cribriform plate of the ethmoid Bones and the superior conchae. These nerves and fibers are stimulated by odorous materials. The resultant nerve impulses are conveyed by the olfactory nerves of the brain, where sensation of smell is perceived.",
          "Modifying speech vibrations as they pass through the large, hollow resonating chambers. Resonance refers to prolonging, amplifying, or modifying a sound by vibration.",
          "Passageway for air: It provides passage way to pharynx."
        ],
