        "title": "Functions of the pharynx",
        "content": [
          "Passageway for food and air: Pharynx plays a major role in the first phase of swallowing. As the food bolus is pushed by the tongue into the pharynx, it pushes the food by muscular contraction down to the esophagus.",
          "Warming and humidifying: Air is further warmed and moistened as it passes through the pharynx.",
          "Hearing: Pharynx equalizes pressure that gets built near the ear drums. This is made possible by two eustachiantubes that connect the middle ear with pharynx. These tubes allow the air to enter the middle ear.",
          "Taste: Nerve endings of the sense of taste are present in the epithelium of the oral and laryngeal parts",
          "Protection: The lymphatic tissue of the pharyngeal tonsils produces antibodies in response to antigens like microbes.",
          "Speech: Acts as a resonating chamber for ascending from the larynx. It along with the sinuses helps to give the voice its individual characteristics."
        ],
