        "content": [
          "Air conduction: This is the primary function of the windpipe or trachea; to allow air passage to your lungs for respiration i.e. to breathe in air rich in oxygen and exhale carbon dioxide.",
          "Protection: Even though the trachea\u2019s main function is the exchange of air, it also helps in protection from microbes and harmful substances. This, in turn, prevents entry of harmful substances into deeper parts of the lungs, which would induce malfunctioning.",
          "Digestive process function:The trachea also plays an important role in the digestive process. Trachea is connected to the tubing system that makes it possible for swallow. Respiratory system has created a mechanism that prevents respiratory failures and choking.",
          "Thermoregulation:This enhances the humidifying and warming of the air that enters the lungs. When there is increased temperature, a system is activated by the body which promotes loss of heat and the body temperature is returned to normal. On the other hand, when the air is too cold, your trachea can warm the air before it enters into your lungs, thus promoting a thermoregulation."
        ],
