          "Respiration occurs in two phases:",
          "Respiration occurs in two phases: Inspiration, expiration. During inspiration, thoracic cage enlarges and lungs expand so that air enters the lungs easily. During expiration, the thoracic cage and lungs decrease in size and attain the pre inspiratory position so that air leaves the lungs easily. During normal quiet breathing, inspiration is the active process and expiration is the passive process."
