        "id": "sec-phys-2-16",
        "title": "Factors preventing collapsing tendency of lungs",
        "content": [
          "Intrapleural pressure: It is the pressure in the pleural cavity, which is always negative. Because of negativity, it keeps the lungs expanded and prevents the collapsing tendency of lungs produced by the elastic tissues.",
          "Surfactant: It is a substance secreted in alveolar epithelium. It reduces surface tension and prevents the collapsing tendency produced by surface tension. Surfactant is a surface acting material or agent that is responsible for lowering the surface tension of a fluid. Surfactant that lines the epithelium of the alveoli in lungs is known as \u2018pulmonary surfactant\u2019 and it decreases the surface tension on the alveolar membrane.",
          "Source of secretion of pulmonary surfactant pulmonary surfactant is secreted by two types of cells:",
          "Type II alveolar epithelial cells in the lungs, which are called \u2018surfactant secreting alveolar cells or pneumocytes\u2019. Characteristic feature of these cells is the presence of Microvilli on their Alveolar Surface.",
          "Clara cells, which are situated in the bronchioles. These cells are also called \u2018bronchiolar exocrine cells\u2019."
        ],
