        "id": "sec-phys-2-19",
        "title": "Respiratory pressures",
        "content": [
          "Two types of pressures are exerted in the thoracic cavity and lungs during process of respiration (Figure 5.1):",
          "1. Intrapleural pressure or intrathoracic pressure",
          "2. Intraalveolar pressure or intrapulmonary pressure.",
          "Intrapleural pressure: Intrapleural pressure is the pressure existing in pleural cavity, that is, in between the visceral and parietal layers of pleura. It is exerted by the suction of the fluid that lines the pleural cavity. It is also called \u2018intrathoracic pressure\u2019since it is exerted in the whole of thoracic cavity."
        ],
