        "id": "sec-phys-2-28",
        "title": "Regulation and Control of Breathing",
        "content": [
          "In order to maintain normal levels of partial oxygen and carbon dioxide pressure both the depth and rate of breathing are precisely regulated. Basic elements of the respiratory control system are (Figure 5.4).",
          "Strategically placed sensors",
          "Central controller",
          "Respiratory muscles.",
          "Central controller:Breathing is mainly controlled at the level of brain stem. The normal automatic and periodic nature of breathing is triggered and controlled by the respiratory centers located in the pons and medulla. These centers are not located in a special nucleus or a group of nuclei but they are rather poor defined collection of neurons.",
          "Medullary respiratory center: Dorsal medullary respiratory neurons are associated with inspiration.It has been proposed that spontaneous intrinsic periodic firing of these neurons responsible for the basic rhythm of breathing. As a result, these neurons exhibit a cycle of activity that arises spontaneously every few seconds and establish the basic rhythm of the respiration. When the neurons are active their action potentials travel through reticulospinal tract in the spinal cord and phrenic and intercostal nerves and finally stimulate the respiratory muscles. Ventral medullary respiratory neurons are associated with expiration.",
          "Apneusticcentre:It is located in the lower pons. Exact role of this centre in the normal breathing is not known. Lesions covering this area in the pons cause a pathologic respiratory rhythm with increased apnea frequency. What is known is nerve impulses from the apneustic center stimulate the inspiratory center and without constant influence of this centre respiration becomes shallow and irregular.",
          "Pneumotaxiccentre:It is located in the upper pons. This centre is a group of neurons that have an inhibitory effect on the both inspiratory and apneustic centers. It is probably responsible for the termination of inspiration by inhibiting the activity of the dorsal medullar neurons. It primarily regulates the volume and secondarily the rate of the respiration. Because in the lesions of this area normal respiration is protected it is generally believed that upper pons is responsible for the fine-tuning of the respiratory rhythm.",
          "Figure 5.4:Regulation and control of respiration."
        ],
