          "1. Pulmonary ventilation",
          "2. Alveolar ventilation.",
          "Pulmonary ventilation:Pulmonary ventilation is defined as the volume of air moving in and out of respiratory tract in a given unit of time during quiet breathing. It is also called \u2018minute ventilation orrespiratory minute volume(RMV)\u2019. Pulmonary ventilation is a cyclic process, by which fresh air enters the lungs and an equal volume of air leaves the lungs."
