          "Total surface area of respiratory membranediffusing capacity is directly proportional to surface area of respiratory membrane. Surface area of respiratory membrane in each lung is about 70 sq m. If the total surface area of respiratory membrane decreases, the diffusing capacity for the gases is decreased. Diffusing capacity is decreased in emphysema in which many of the alveoli are collapsed because of heavy smoking or oxidant gases.",
          "Molecular weight of the gas diffusing capacity is inversely proportional to molecular weight of the gas. If the molecular weight is more, the density is more and the rate of diffusion is less.",
