        "title": "Functions of digestive system",
        "content": [
          "Ingestion:Involves taking foods and liquids into the mouth (eating).",
          "Secretion:Thecells within the walls of the GI tract and accessory digestive organs secrete a total of about 7 liters of water, acid, buffers, and enzymes into the lumen (interior space) of the tract every day.",
          "Mixing andPropulsion: Alternating contractions and relaxations of smooth muscle in the walls of the GI tract mix food and secretions and propel them toward the anus. This capability of the GI tract to mix and move material along its length is called \u2018motility\u2019.",
          "Digestion: Mechanical and chemical processes break down ingested food into small molecules. In mechanicaldigestion the teeth cut and grind food before it is swallowed, and then smooth muscles of the stomach and small intestine churn the food. As a result, food molecules become dissolved and thoroughly mixed with digestive enzymes.In chemicaldigestionthe large carbohydrate, lipid, protein, and nucleic acid molecules are split into smaller molecules by hydrolysis.Digestive enzymes produced by the salivary glands, tongue, stomach, pancreas, and small intestine catalyze these catabolic reactions. A few substances in food can be absorbed without chemical digestion. These include vitamins, ions, cholesterol, and water.",
          "Absorption: The entrance of ingested and secreted fluids, ions and the products of digestion into the epithelial cells lining the lumen of the GI tract are called \u2018absorption\u2019.",
          "Defecation:Wastes, indigestible substances, bacteria, and cells sloughed from the lining of the GI tract, and digested materials that were not absorbed through the digestive tract leave the   body through the anus in a process called \u2018defecation\u2019.The eliminated material is termed \u2018feces or stool\u2019."
        ],
