          "Digestive enzymes are salivary amylase, maltase and lingual lipase.",
          "Salivary amylase is a carbohydrate digesting (amylolytic) enzyme. It acts on cooked or boiled starch and converts it into dextrin and maltose.",
          "Maltase is present only in traces in human saliva and it converts maltose into glucose.",
          "Lingual lipase is a lipid digesting (lipolytic) enzyme. It hydrolyzes triglycerides into fatty acids and diacylglycerol"
