        "id": "sec-phys-3-9",
        "title": "Cleansing and protective functions",
        "content": [
          "Constant secretion of saliva, the mouth and teeth are rinsed and kept free off food debris; shed epithelial cells and foreign particles.",
          "Saliva kills some bacteria such as staphylococcus, streptococcus and brucella.",
          "Proline-rich proteins present in saliva possess antimicrobial property and neutralize the toxic substances such as tannins",
          "Lactoferrin of saliva also has antimicrobial property.",
          "Proline-rich proteins and lactoferrinprotect the teeth by stimulating enamel formation.",
          "Immunoglobulin IgA in saliva also has antibacterial and antiviral actions.",
          "Mucin present in the saliva protects the mouth by lubricating the mucus membrane of mouth.",
          "Role in speech: By moistening and lubricating soft parts of Mouth and Lips, Saliva Helps in Speech.",
          "Excretory function: Many substances, both organic and inorganic, are excreted in saliva. It excretes substances like mercury, potassium iodide, lead, and thiocyanate. Saliva also excretes some viruses such as those causing rabies and mumps.",
          "Regulation of body temperature: Excessive dripping of saliva during panting helps in the loss of heat and regulation of body temperature in animals but in human saliva does not play any role.",
          "Regulation of water balance: When the body water content decreases, salivary secretion also decreases.  When water is taken, it quenches the thirst and restores the body water content.",
          "Regulation of salivary secretion: Salivary secretion is regulated by Autonomic Nervoues System.",
          "Relationship of Parasympathetic fibers in salivary secretion:Parasympathetic fibers to submandibular and sublingual glands: parasympathetic preganglionic fibers (Figure 6.2) to parotid gland arise from inferior salivatory nucleus situated in the upper part of medulla oblongata.",
          "Figure 6.2: Parasympathetic nerve supply to sub maxillary and sublingual gland."
        ],
