          "Digestive function: Gastric juice acts mainly on proteins. Proteolytic enzyme of the gastric juice is pepsin and rennin. Gastric juice also contains some other enzymes like gastric lipase, gelatinase, urase and gastric amylase which help in digestion of the stomach.",
          "Protective function: Mucus is a mucoprotein, secreted by mucus neck cells of the gastric glands and surface mucus cells in fundus, body and other parts of stomach. It protects the gastric wall.",
          "Hemopoietic function: Intrinsic factor of castle, secreted by parietal cells of gastric glands plays an important role in erythropoiesis. It is necessary for the absorption of vitamin B12 (which is called \u2018extrinsic factor\u2019) from GI tract into the blood. Vitamin B12 is an important maturation factor during erythropoiesis",
          "Excretory function: Many substances like toxins, alkaloids and metals are excreted through gastric juice."
