        "id": "sec-phys-3-23",
        "title": "Nervous Mechanism",
        "content": [
          "Local myenteric reflex: It is the reflex elicited by stimulation of myenteric nerve plexus in stomach wall. After entering stomach, the food particles stimulate the local nerve plexus present in the wall of the stomach. These nerve fibers release acetylcholine, which stimulates the gastric glands to secrete a large quantity of gastric juice. Simultaneously, acetylcholine stimulates G cells to secrete gastrin.",
          "Vasovagal reflex: Vasovagal reflex is the reflex which involves both afferent and efferent vagal fibers. Entrance of bolus into the stomach stimulates the sensory (afferent) nerve endings of vagus and generates sensory impulses. These sensory impulses are transmitted by sensory fibers of vagusto dorsal nucleus of vagus, located in medulla of brainstem. This nucleus in turn, sends efferent impulses through the motor (efferent) fibers of vagus, back to the stomach and cause secretion of gastric juice. Since, both afferent and efferent impulses pass through vagus, this reflex is called \u2018vasovagal reflex\u2019."
        ],
