        "id": "sec-phys-3-26",
        "title": "Spleen",
        "content": [
          "The\u00a0spleen\u00a0breaks down both red and white\u00a0blood cells\u00a0that are\u00a0spent. This is why it is sometimes known as the 'Graveyard of Red Blood Cells\u2019. A product of this\u00a0digestion\u00a0is the pigment\u00a0bilirubin\u00a0which is sent to the\u00a0liver\u00a0and secreted in the\u00a0 HYPERLINK \"https://en.wikipedia.org/wiki/Bile\" \\o \"Bile\" bile.Another product is\u00a0iron\u00a0which is used in the formation of new blood cells in the\u00a0bone marrow.\u00a0Western medicine\u00a0treats the spleen solely as belonging to the\u00a0lymphatic system, though it is acknowledged that the full range of its important functions is not yet understood.\u00a0In contrast to this view,\u00a0traditional Chinese medicine\u00a0sees the spleen to be of central importance in the digestive system.",
          "The role of the spleen is seen to affect the health and vitality of the body in its turning of digested material from the stomach into usable nutrients and energy. Symptoms that include poor appetite, indigestion, bloating and jaundice, are seen to be indications of an imbalance in the spleen. The spleen is further seen to play a part in the metabolism of water, in ridding the body of excess fluid.\u00a0In the west, the spleen is seen to be paired with the stomach but in Chinese medicine, reference is made to the spleen system, which involves the pancreas.",
          "Fluids in the body are seen in traditional Chinese medicine to be under the control of the spleen. Fluids include digestive enzymes, saliva, and mucus, fluid in the joints, tears, sweat and urine. They are categorized as thin and thick and together they are seen as nourishing all tissues and organs."
        ],
