        "title": "Composition of bile",
        "content": [
          "Bile contains (Figure 6.5) 97.6% of water and 2.4% of solids. Solidsinclude organic and inorganic substances.",
          "Figure 6.5:Composition of bile."
        ],
        "points": [
          "Figure 6.5:Composition of bile."
        ],
        "clinicalPearl": "**Clinical Pearl:** Jaundice or icterus is the condition characterized by yellow coloration of the skin, mucous membrane and deeper tissues due to increased bilirubin level in blood.",
        "images": [
          {
            "src": "/images/physiology/diagram_sec-phys-3-32.svg",
            "caption": "Composition of bile • Anatomical Architecture & Landmark Guide",
            "alt": "Composition of bile"
          }
        ]
