        "id": "sec-phys-3-38",
        "title": "Functions of pancreatic juice",
        "content": [
          "Pancreatic juice has digestive functions and neutralizing action.",
          "Digestive functions of pancreatic juice: Pancreatic juice plays an important role in the digestion of proteins and lipids. It also has mild digestive action on carbohydrates.",
          "Digestion of proteins: Major proteolytic enzymes of pancreatic juice are trypsin and chymotrypsin. Other proteolytic enzymes are carboxypeptidases, nuclease, elastase and collagenase.",
          "Trypsin: Trypsin is a single polypeptide with a molecular weight of 25,000. It contains 229 amino acids."
        ],
        "points": [
          "Digestion of proteins: Major proteolytic enzymes of pancreatic juice are trypsin and chymotrypsin. Other proteolytic enzymes are carboxypeptidases, nuclease, elastase and collagenase.",
          "Trypsin: Trypsin is a single polypeptide with a molecular weight of 25,000. It contains 229 amino acids."
        ],
        "clinicalPearl": "**Clinical Pearl:** Pancreatitis:is the inflammation of pancreatic acini. It is a rare but dangerous disease. Pancreatitis is of two types: Acute pancreatitis, chronic pancreatitis.",
