        "title": "Functions of small intestine",
        "content": [
          "Mechanical function: Mixing movements of small intestine help in the thorough mixing of chyme with the digestive juices like succus entericus, pancreatic juice and bile.",
          "Secretory function: Small intestine secretes succus entericus, enterokinase and the GI hormones.",
          "Hormonal function: Small intestine secretes many GI hormones such as secretin, cholecystokinin, etc. These hormones regulate the movement of GI tract and secretory activities of small intestine and pancreas.",
          "Digestive function:Enzymes of succus entericus act on the partially digested food and convert them into final digestive products. Enzymes are produced and released into succus entericus by enterocytes of the villi.",
          "Proteolytic enzymes:Proteolytic enzymes present in succus entericus are the peptidases. These peptidases convert peptides into amino acids.",
          "Amylolytic enzymes:Amylolytic enzymes of succus entericus are lactase, sucrase and maltase convert the disaccharides (lactose, sucrose and maltose) into two molecules of monosaccharides.Dextrinase converts dextrin, maltose and maltriose into glucose. Trehalase or trehaloseglucohydrolase causes hydrolysis of trehalose (carbohydrate present in mushrooms and yeast) and converts it into glucose.",
          "Lipolytic Enzyme:Intestinal lipase acts on triglycerides and converts them into fatty acids.",
          "Activator function:Enterokinase present in intestinal juice activates trypsinogen into trypsin. Trypsin, in turn activates other enzymes",
          "Hemopoietic function:Intrinsic factor of castlepresent in the intestine plays an important role in erythropoiesis. It is necessary for the absorption of vitamin B12.",
          "Hydrolytic function: Intestinal juice helps in all the enzymatic reactions of digestion.",
          "Absorptive functions:Presence of villi and microvilli in small intestinal mucosa increases the surface area of mucosa. This facilitates the absorptive function of intestine. Digested products of foodstuffs, proteins, carbohydrates, fats and other nutritive substances such as vitamins, minerals and water are absorbed mostly in small intestine. From the lumen of intestine, these substances pass through lacteal of villi, cross the mucosa and enter the blood directly or through lymphatics."
        ],
