        "clinicalPearl": "**Clinical Pearl:** Esophageal achalasia or achalasia cardia: esophageal achalasia or achalasia cardia is a neuromuscular disease, characterized by accumulation of food substances in the esophagus preventing normal swallowing. It is due to the failure of lower esophageal (cardiac) sphincter to relax during swallowing.",
