          "Changes in blood gas composition also affect heart rate. Hypoxia, Hypercapnia, acidosis causes tachycardia.",
          "Increased body temperature causes tachycardia by direct action on SA node",
          "Peripheral resistance",
          "Blood Pressure",
          "Blood pressure is the pressure exerted by the blood on the walls of the blood vessels. Unless indicated otherwise, blood pressure refers to systemic arterial blood pressure, i.e., the pressure in the large arteries delivering blood to body parts other than the lungs, such as the brachial artery (in the arm). The pressure of the blood in other vessels is lower than the arterial pressure. Blood pressure values are universally stated in millimetres of mercury (mmHg). The systolic pressure is defined as the peak pressure in the arteries during the cardiac cycle; the diastolic pressure is the lowest pressure (at the resting phase of the cardiac cycle). The mean arterial pressure and pulse pressure are other important quantities. Typical values for a resting, healthy adult are approximately 120 mmHg systolic and 80mm Hg diastolic (written as 120/80 mmHg), with individual variations. These measures of blood pressure are not static, but undergo natural variations from one heartbeat to another, and throughout the day (in a circadian rhythm); they also change in response to stress, nutritional factors, drugs, or disease. Sphygmomanometer is the instrument used to measure blood pressure.",
          "Systolic pressure: Systolic Pressure is the highest when the blood is being pumped out of the left ventricle into the aorta during ventricular systole. The average high during systole is 120 mmHg.",
