        "id": "subj-phys-4-21",
        "question": "Lymph contains a variety of substances, including proteins, salts, glucose, fats, water, and white blood cells. Lymph does not normally contain any red blood cells.",
        "answer": "INC standard: Detail anatomical landmarks, physiological mechanisms, and clinical nursing management for Lymph contains a variety of substances, including proteins, salts, glucose, fats, water, and white blood cells. Lymph does not normally contain any red blood cells..",
