        "question": "Adaptive immunity is based on specific response to a specific response to a specific microbe; that is, it adapts or adjusts to handle a specific microbe. Unlike innate immunity, adaptive immunity is slower to respond, but it does have a memory component. Adaptive immunity involves lymphocytes (a type of white blood cells) called \u2018T- Lymphocytes and B lymphocytes\u2019.",
        "answer": "INC standard: Detail anatomical landmarks, physiological mechanisms, and clinical nursing management for Adaptive immunity is based on specific response to a specific response to a specific microbe; that is, it adapts or adjusts to handle a specific microbe. Unlike innate immunity, adaptive immunity is slower to respond, but it does have a memory component. Adaptive immunity involves lymphocytes (a type of white blood cells) called \u2018T- Lymphocytes and B lymphocytes\u2019..",
