        "id": "subj-phys-4-100",
        "question": "Humoral (antibody mediated) Immunity: Humoral immunity, also called the \u2018antibody mediated beta cellular immune system\u2019, is the aspect of immunity that is mediated by macromolecules as opposed to cell mediated immunity, found in extracellular fluids such as secreted antibodies, complement proteins and certain antimicrobial peptides. Humoral immunity is so named because it involves substances found in the humours, or body fluids.",
