        "question": "Inflammation is a nonspecific, defensive response (Figure 3.7) of the body to tissue damage. Among the conditions that may produce inflammation are pathogens, abrasions, chemical irritations, distortion or disturbances of cells, and extreme temperatures. The four characteristic signs and symptoms of inflammation or cardinal signs are redness, pain, heat, and swelling. Inflammation can also cause the loss of function in the injured area, e.g. the inability to detect sensations.",
