          "Role in transport mechanism: Plasma proteins are essential for the transport of various substances in the blood. Albumin, alpha globulin and beta globulin are responsible for the transport of the hormones and enzymes.",
          "Role in viscosity of blood: Plasma proteins provide viscosity to the blood, which is important to maintain the blood pressure. Albumin provides maximum viscosity than the other plasma proteins.",
