          "Platelets have three important properties (three \u2018A\u2019s):",
          "Adhesiveness: Adhesiveness is the property of sticking to a rough surface.",
          "Aggregation: Aggregation is the grouping of platelets.",
          "Agglutination: Agglutination is the clumping together of platelets."
