          "Functions of Anterior Pituitary Hormones",
          "The anterior pituitary produces 7 important hormones:",
          "Thyroid stimulating hormone (TSH): TSH is necessary for the growth and secretory activity of the thyroid gland. It has many actions on the thyroid gland.",
          "Adrenocorticotropic hormone (ACTH): ACTH is necessary for the structural integrity and the secretory activity of adrenal cortex.",
          "Follicle stimulating hormone (FSH): Follicle-stimulating hormone is a glycoprotein made up of one \u03b1-subunit and a \u03b2-subunit. The \u03b1-subunit has 92amino acids and \u03b2-subunit has 118 amino acids. The half-life of FSH is about 3 to 4 hours."
