          "Functions of the Thymus Gland",
          "The Thymus (Figure 10.3) is a soft, triangular-shaped organ found in the chest posterior to the sternum. The thymus produces hormones called \u2018thymosin\u2019 that help to train and develop T-lymphocytes during fetal development and childhood. The T-lymphocytes produced in the thymus go on to protect the body from pathogens throughout a person\u2019s entire life. The thymus becomes inactive during puberty and is slowly replaced by adipose tissue throughout a person\u2019s life.",
