          "Synthesis of thyroid hormones: Synthesis of thyroid hormones (Figure 10.4) takes place in thyroglobulin, present in follicular cavity. Iodine and tyrosine are essential for the formation of thyroid hormones. Iodine is consumed through diet. It is converted into iodide and absorbed from GI tract. Tyrosine is also consumed through diet and is absorbed from the GI tract. For the synthesis of normal quantities of thyroid hormones; approximately 1 mg of iodine is required per week or about 50 mg per year. To prevent iodine deficiency, common table salt is iodized with one part of sodium iodide to every 100,000 parts of sodium chloride.",
