        "id": "sec-phys-6-22",
        "title": "Parathormone receptors",
        "content": [
          "Parathormone receptors (PTH receptors) are of three types, PTHR1, PTHR2 and PTHR3, which are G protein coupled receptors. PTHR1 is physiologically more important than the other two types. PTHR1 mediates the actions of PTH and PTH-related protein.",
          "Role of PTHR2 and PTHR3 is not known clearly.",
          "On the target cells, PTH binds with PTHR1 which is coupled to G protein and forms hormone-receptor complex. Hormone-receptor complex causes formation of cAMP, which acts as a second messenger for the hormone."
        ],
