        "clinicalPearl": "**Clinical Pearl:** Congenital adrenal hyperplasia: Congenital adrenal hyperplasia is a congenital disorder, characterized by increase in size of adrenal cortex. Size increases due to abnormal increase in the number of steroid-secreting cortical cells.",
        "images": [
          {
            "src": "/images/physiology/diagram_sec-phys-6-24.svg",
            "caption": "Functions of Ovaries, Testes and Placenta • Anatomical Architecture & Landmark Guide",
            "alt": "Functions of Ovaries, Testes and Placenta"
          }
        ]
