          "Functions of the Skin",
          "The skin is an ever changing organ that contains many specialized cells and structures (Figure 12.1). The skin function as a protective barrier, that interfaces with a sometimes- hostile environment. It is also very involved in maintaining the proper temperature for the body to function well. It gathers sensory information from the environment and plays an active role in the immune system protecting us from disease. Other functions include synthesis of vitamin D and storage of fat and absorption of vitamin C.",
          "The common functions of skin is",
