          "Excretion: Sweat glands can provide excellent route for excretion of water and electrolytes. If perspiration continuous for a long period is a dangerous, fluid electrolytes imbalance can occur. This is the reason why athletes have to pause frequently to drink fluids.",
          "Protection: Sweat glands provide protection from environmental hazards by diluting chemicals and discouraging the growth of microorganisms."
