        "title": "Hair",
        "content": [
          "It is a protein filament that grows through epidermis from hair follicles lying in the dermis. Invigilating of epidermis occurs in the dermis to form hair follicle. The hair follicle is a pouch like structure which lodges the root of hair. From the root emerges the shaft of hair. The root of hair is beneath the surface of the skin while the shaft is above it. The color of hair is determined by the amount of melanin pigment present in it. As age advances, melanin pigment is replaced by air bubbles which results in graying of hair.",
          "Arrestors pilorum",
          "They are smooth muscle fiber which is attached to hair follicles. On contraction it gives rise to goose pimples."
        ],
