          "Functions of the Eye",
          "The stabilization of eye movement is accomplished by six extra ocular muscles that attach to each eyeball and perform their horizontal and vertical movement and rotation. These muscles are controlled by impulse from the cranial nerves that tell the muscles to contract or to relax. When certain muscles contract and other relax, the eye moves."
