          "Action of acetylcholine: After entering the synaptic cleft, acetylcholine molecules bind with nicotinic receptors present in the postsynaptic membrane and form acetylcholine receptor complex. It increases the permeability of postsynaptic membrane for sodium by opening the ligand-gated sodium channels.",
