        "id": "sec-phys-9-14",
        "title": "Elements of the body",
        "content": [
          "The largest constituent of the body is water, which is 60 % of the total body weight. The correct proportion of water and electrolytes in the water and proper acid base balance are necessary for life to exist. Loss of 10% of total body water usually produce lethargy, fever and dryness on mucous membrane and a 20% loss is fatal.",
          "Body fluids:",
          "All body fluids are either intracellular (inside the cell) or extra cellular (out of the cell) fluids. Intracellular fluid constitutes 2/3 of all body fluid. Extra cellular fluids found as interstitial fluid (the immediate environment of body cells), blood plasma and lymph, cerebrospinal, synovial, fluids of the eye & ear, pleural, pericardial, peritoneal, gastrointestinal and glomerular filtrate of the kidney. The most important and abundant fluids are the interstitial & blood plasma. The interstitial fluid occupies the space around body cells. It is derived from blood plasma. - The most important difference between the plasma and interstitial fluid is the presence of soluble protein in plasma and they are near absence in the interstitial fluid."
        ],
