          "The Placenta truly is an organ of life with a number of functions designed to provide for and product the fetus. Its functions include respiration, nutrition, storage, production and endocrine.",
          "Respiration:",
          "The fetus obtains oxygen and excretes carbon dioxide through the Placenta. Oxygen from the mother\u2019s hemoglobin passes into the fetal blood by simple diffusion and similarly the fetus gives off carbon dioxide into the maternal blood."
