          "Embryology is the branch of biology and medicine concerned with the study of embryos and their development.",
          "The embryo is defined as the developing pregnancy from the time of fertilization until the end of the eighth week of gestation, when it becomes known as Fetus. In humans, an Embryo is generally considered to be between the first and the eighth week of development after fertilization, and from then it is instead called a \u2018fetus\u2019. Some definitions consider embryological life to start at the third week of development to the eighth, when most organ systems are developing.",
          "The development of the embryo is called \u2018embryogenesis\u2019 (Figure 9.7). Once a sperm fertilizes an egg cell, the result is a cell called the \u2018zygote\u2019, which possesses half the Deoxyribose nucleic acid (DNA) of each of its two parents. The result of this process is an embryo.",
