        "title": "Ejaculation",
        "content": [
          "The Ejaculatory process is mainly mediated by the autonomic nervous system, and consists of two main phases: emission and expulsion.\u00a0Two groups of anatomical structures are specifically involved and distinguished in each phase. The organs involved in the emission phase comprise the epididymis, vas deferens, seminal vesicles, prostate gland, prostatic urethra and bladder neck.",
          "The organs participating in the expulsion phase include the bladder neck and urethra, as well as the pelvic striated muscles. Ejaculation\u00a0is the discharge of\u00a0semen\u00a0(usually carrying\u00a0sperm) from the\u00a0male reproductive tract. It usually occurs during an\u00a0orgasm. It is usually the final stage and natural objective of male\u00a0sexual stimulation, and an essential component of natural\u00a0conception.",
          "In rare cases, ejaculation occurs because of\u00a0prostatic disease. Ejaculation may also occur spontaneously during\u00a0sleep\u00a0(Nocturnal Emission  \u00a0or \u2018Wet Dream\u2019).  The anejaculation is the condition of being unable to ejaculate. The dysejaculation is ejaculation that is painful or uncomfortable."
        ],
