        "id": "sec-phys-10-31",
        "title": "Male Fertility",
        "content": [
          "Fertility\u00a0is the natural capability to produce offspring. Fertility is defined as the\u00a0potential\u00a0for reproduction (influenced by\u00a0gamete\u00a0production, fertilization and carrying a pregnancy to term) A lack of fertility is infertility\u00a0while a lack of fecundity would be called \u2018sterility\u2019.",
          "Increased male age is associated with a decline in semen volume,\u00a0sperm motility, and sperm morphology.  In studies that controlled for female age, comparisons between men under 30 and men over 50 found relative decreases in\u00a0pregnancy rates\u00a0between 23% and 38%.",
          "Sperm count\u00a0declines with age, with men aged 50\u201380 years producing sperm at an average rate of 75% compared with men aged 20\u201350 years. However, an even larger difference is seen in how many of the\u00a0seminiferous tubules\u00a0in the\u00a0testes\u00a0contain mature sperm;",
          "In males 20\u201339 years old, 90% of the seminiferous tubules contain mature sperm.",
          "In males 40\u201369 years old, 50% of the seminiferous tubules contain mature sperm.",
          "In males 80 years old and older, 10% of the seminiferous tubules contain mature sperm.",
          "Decline in male fertility is influenced by many factors, including of\u00a0nutrition,\u00a0sexual behavior,\u00a0consanguinity,\u00a0culture,\u00a0endocrinology, timing,\u00a0economics, way of life, and\u00a0emotions lifestyle, environment and psychological factors."
        ],
