          "Mandibular division (V3): from anterior tongue, lower teeth, skin of chin, and temporal region of scalp through the foramen ovale. Dentist desensitizes upper and lower jaws by injecting local anesthetic into alveolar branches of maxillary and mandibular division respectively."
