          "Acquired reflexes: Learned and typically more complex motor patterns. e.g. a professional skier makes quick adjustments in body positioning while racing.",
          "Cranial reflexes: Reflexes processed in the brain.",
          "Spinal reflexes: Interconnections and processing events occur in the spinal cord.",
          "Somatic reflexes: Control skeletal muscle.",
